import zipfile
import re
import xml.etree.ElementTree as ET
from collections import OrderedDict

path = "budget.xlsx"
z = zipfile.ZipFile(path)

def local(tag):
    return tag.split('}')[-1]

# Sheet name -> file target via workbook.xml + rels
wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
rels_xml = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
rid_to_target = {}
for rel in rels_xml:
    if local(rel.tag) == "Relationship":
        rid_to_target[rel.attrib.get("Id")] = rel.attrib.get("Target")

sheets = []
for sh in wb_xml.iter():
    if local(sh.tag) == "sheet":
        rid = sh.attrib.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        name = sh.attrib.get("name")
        target = rid_to_target.get(rid)
        if not target.startswith("xl/"):
            target = "xl/" + target
        sheets.append((name, target))

# Shared strings
shared = []
if "xl/sharedStrings.xml" in z.namelist():
    ss_xml = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in ss_xml.iter():
        if local(si.tag) == "si":
            text = "".join(t.text or "" for t in si.iter() if local(t.tag) == "t")
            shared.append(text)

COL_RE = re.compile(r"([A-Z]+)(\d+)")

def col_to_idx(col):
    n = 0
    for ch in col:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n - 1

grand_total = 0.0
for name, target in sheets:
    ws = ET.fromstring(z.read(target))
    cells = {}
    max_row = 0
    max_col = 0
    for row in ws.iter():
        if local(row.tag) == "row":
            r = int(row.attrib.get("r"))
            for c in row:
                if local(c.tag) != "c":
                    continue
                ref = c.attrib.get("r")
                m = COL_RE.match(ref)
                if not m:
                    continue
                col_letters, row_num = m.group(1), int(m.group(2))
                ci = col_to_idx(col_letters)
                t = c.attrib.get("t")
                v = c.find("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v")
                value = None
                if v is not None and v.text is not None:
                    raw = v.text
                    if t == "s":
                        value = shared[int(raw)]
                    elif t == "str" or t == "inlineStr":
                        value = raw
                    elif t == "b":
                        value = raw == "1"
                    else:
                        try:
                            value = float(raw)
                        except ValueError:
                            value = raw
                cells[(row_num - 1, ci)] = value
                max_row = max(max_row, row_num)
                max_col = max(max_col, ci + 1)

    print(f"=== Sheet: {name} ===")
    header = " | ".join(f"{chr(65+i)}" for i in range(max_col))
    for ri in range(max_row):
        row_vals = []
        for ci in range(max_col):
            val = cells.get((ri, ci))
            if isinstance(val, float) and val == int(val):
                val = int(val)
            row_vals.append("" if val is None else str(val))
        print(f"R{ri+1}: " + " | ".join(row_vals))

    # Column sums of numeric values (excluding the header row)
    col_sums = OrderedDict()
    for ci in range(max_col):
        total = 0.0
        has_num = False
        for ri in range(1, max_row):
            val = cells.get((ri, ci))
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                total += val
                has_num = True
        if has_num:
            col_sums[chr(65 + ci)] = total
            grand_total += total
    print("Column sums (numeric, excluding header):", dict(col_sums))
    print()

print(f"GRAND TOTAL EXPENSES ACROSS ALL CATEGORIES: {grand_total}")

